(npm start >$TMPDIR/srv.log 2>&1 &) && sleep 2 && cat > $TMPDIR/shot.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  for (const [w,h,n] of [[1280,900,'desk'],[390,800,'mob']]) {
    const p = await b.newPage({viewport:{width:w,height:h}});
    await p.goto(`http://127.0.0.1:${process.env.PORT}/products.html`);
    await p.screenshot({path:`${process.env.TMPDIR}/${n}.png`, fullPage:true});
    const r = await p.evaluate(()=>({sw:document.documentElement.scrollWidth, cards:[...document.querySelectorAll('.card')].map(c=>{const b=c.getBoundingClientRect();return [b.x|0,b.y|0,b.width|0,b.height|0]}), badges:[...document.querySelectorAll('.badge')].map(c=>{const b=c.getBoundingClientRect();return [b.x|0,b.y|0,b.width|0]})}));
    console.log(n, JSON.stringify(r));
  }
  await b.close();
})();
EOF
NODE_PATH=$PWD/node_modules node $TMPDIR/shot.js

